const NG_STATUTORY_RULE_2026: PayrollStatutoryRule = { version: "NG-2026-NTA", jurisdiction: "NG", effectiveFrom: "2026-01-01", paye: { bands: [{ threshold: 800000, rate: "0" }, { threshold: 2200000, rate: "0.15" }, { threshold: 9000000, rate: "0.18" }, { threshold: 13000000, rate: "0.21" }, { threshold: 25000000, rate: "0.23" }, { threshold: null, rate: "0.25" }], annualDeductions: ["EMPLOYEE_PENSION", "NHF"], remittanceDueDay: 10 }, pension: { employeeRate: "0.08", employerRate: "0.10", basis: ["BASIC", "HOUSING", "TRANSPORT"] }, nhf: { employeeRate: "0.025", basis: "BASIC" }, nsitf: { employerRate: "0.01", basis: "GROSS" } };
