const resolvePayrollStatutoryRule = async (organizationId: string, period: string, client: Prisma.TransactionClient | typeof prisma = prisma) => { const row = await client.systemConfig.findUnique({ where: { organizationId_key: { organizationId, key: "payroll.statutory.rules" } }, select: { value: true, rowVersion: true } }); const configured = Array.isArray(row?.value) ? row.value.map(statutoryRuleFromConfig).filter(Boolean) as PayrollStatutoryRule[] : []; const applicable = configured.filter((rule) => rule.effectiveFrom.slice(0, 7) <= period).sort((a, b) => b.effectiveFrom.localeCompare(a.effectiveFrom))[0] ?? (period >= "2026-01" ? NG_STATUTORY_RULE_2026 : null); if (!applicable) throw conflict(`No statutory rule is configured for payroll period ${period}`); return { rule: applicable, source: configured.includes(applicable) ? "SYSTEM_CONFIG" : "BUILT_IN", rowVersion: row?.rowVersion ?? 0 }; };
