const payrollPayeeActiveRunStatuses = ["DRAFT", "PROCESSING", "PENDING_APPROVAL", "APPROVED", "PENDING_DISBURSEMENT", "DISBURSING"] as const;
const maskPayeeAccount = (value: string | null) => value ? `${"*".repeat(Math.max(0, value.length - 4))}${value.slice(-4)}` : null;
const maskPayeeTin = (value: string | null) => value ? `***${value.slice(-4)}` : null;
const payeePagination = (page: number, limit: number, total: number) => ({ page, limit, total, totalPages: Math.ceil(total / limit) });
