const payeeProjection = (row: any, detail = false) => ({ id: row.id, name: row.name, type: row.type, status: row.status, email: row.email, phone: row.phone, monthlyAmount: Number(row.monthlyAmount), isTaxable: row.isTaxable, bank: { bankName: row.bankName, bankCode: row.bankCode, accountNumber: maskPayeeAccount(row.accountNumber), ...(detail ? { accountName: row.accountName } : {}) }, ...(detail ? { tin: maskPayeeTin(row.tin), createdAt: row.createdAt, updatedAt: row.updatedAt } : {}) });
const payrollPayee = async (organizationId: string, payeeId: string, includeRemoved = false) => { const payee = await prisma.payee.findFirst({ where: { id: payeeId, organizationId, ...(includeRemoved ? {} : { deletedAt: null }) } }); if (!payee) throw notFound("Payee not found"); return payee; };
