export const getPayrollPayee = async (organizationId: string, payeeId: string) => payeeProjection(await payrollPayee(organizationId, payeeId), true);
export const createPayrollPayee = async (organizationId: string, input: any, user: AuthUser) => { const row = await prisma.payee.create({ data: { organizationId, ...input } }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PAYEE_CREATED", resource: "PAYEE", resourceId: row.id, summary: `Created payee ${row.name}`, metadata: { payeeId: row.id, type: row.type, isTaxable: row.isTaxable } }); return payeeProjection(row, true); };
