export const inspectPayrollPayeeDocument = (file: Express.Multer.File) => { const jpeg = file.buffer.length >= 3 && file.buffer[0] === 0xff && file.buffer[1] === 0xd8 && file.buffer[2] === 0xff; const png = file.buffer.length >= 8 && file.buffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])); const pdf = file.buffer.length >= 5 && file.buffer.subarray(0, 5).toString("ascii") === "%PDF-"; if (!(file.mimetype === "image/jpeg" ? jpeg : file.mimetype === "image/png" ? png : file.mimetype === "application/pdf" ? pdf : false)) throw badRequest("Payee document content does not match its declared type"); };
