export const buildLoanSchedule = (principal: Prisma.Decimal, repayment: Prisma.Decimal, startDate: Date, status = "ACTIVE") => { const rows = []; let balance = principal; let index = 0; while (balance.gt(0) && index < 1200) { const amount = Prisma.Decimal.min(repayment, balance); const date = new Date(Date.UTC(startDate.getUTCFullYear(), startDate.getUTCMonth() + index, startDate.getUTCDate())); const closing = balance.sub(amount); rows.push({ installment: index + 1, month: date.toISOString().slice(0, 7), date, openingBalance: Number(balance), repayment: Number(amount), closingBalance: Number(closing), installmentStatus: status === "PAUSED" ? "PAUSED" : date <= new Date() ? "CURRENT_OR_DUE" : "SCHEDULED", isCurrent: date.toISOString().slice(0, 7) === new Date().toISOString().slice(0, 7) }); balance = closing; index += 1; } return rows; };
