  const writes: Prisma.PrismaPromise<unknown>[] = []; for (const run of runs) { const groups = new Map<string, { state: string; code: string; name: string | null; amount: Prisma.Decimal; count: number }>(); for (const slip of run.payslip) { const authority = jsonRecord(slip.taxAuthoritySnapshot); const resolved = authority.code ? { state: String(authority.state ?? slip.taxStateSnapshot ?? "UNCONFIGURED"), code: String(authority.code), name: authority.name ? String(authority.name) : null } : authorityForState(slip.taxStateSnapshot, config.get("payroll.tax-authorities")); const group = groups.get(resolved.code) ?? { ...resolved, amount: zeroDecimal(), count: 0 }; group.amount = group.amount.add(slip.payeTax); group.count += 1; groups.set(resolved.code, group); } const period = run.periodStart.toISOString().slice(0, 7); for (const group of groups.values()) writes.push(prisma.payrollTaxRemittance.upsert({ where: { organizationId_payrollRunId_authorityCode: { organizationId, payrollRunId: run.id, authorityCode: group.code } }, create: { organizationId, payrollRunId: run.id, period, state: group.state, authorityCode: group.code, authorityName: group.name, employeeCount: group.count, amount: group.amount, dueDate: payeDueDate(period, config.get("payroll.paye.config")) }, update: {} })); }
