    if (sourceType === "TAX_REPORT") { const source = await tx.taxReport.findFirst({ where: { id: sourceId, organizationId, submittedAt: null, type: { in: ["PENSION", "NHF"] } } }); if (!source) throw conflict("Statutory obligation is not payable"); amount = source.amount; type = `${source.type}_REMITTANCE`; description = `${source.type} remittance`; }
