export const listPayrollWalletTransactions = async (organizationId: string, query: any) => { const where: Prisma.WalletTransactionWhereInput = { organizationId, ...(query.type ? { type: query.type } : {}), ...(query.direction ? { direction: query.direction } : {}), ...(query.search ? { OR: [{ description: { contains: query.search } }, { reference: { contains: query.search } }, { transferReference: { contains: query.search } }] } : {}), ...(query.from || query.to ? { createdAt: { ...(query.from ? { gte: new Date(`${query.from}T00:00:00.000Z`) } : {}), ...(query.to ? { lte: new Date(`${query.to}T23:59:59.999Z`) } : {}) } } : {}) }; const [rows, total] = await Promise.all([prisma.walletTransaction.findMany({ where, orderBy: { createdAt: "desc" }, skip: (query.page - 1) * query.limit, take: query.limit }), prisma.walletTransaction.count({ where })]); return { transactions: rows.map(walletTransactionDto), pagination: payeePagination(query.page, query.limit, total) }; };
export const getPayrollWalletTransaction = async (organizationId: string, id: string) => { const row = await prisma.walletTransaction.findFirst({ where: { id, organizationId } }); if (!row) throw notFound("Wallet transaction not found"); return walletTransactionDto(row); };
export const exportPayrollWalletTransactions = async (organizationId: string, query: any) => { const result = await listPayrollWalletTransactions(organizationId, { ...query, page: 1, limit: 100 }); return `\uFEFF${[["Date", "Description", "TransactionType", "Reference", "Direction", "Amount", "BalanceAfter"], ...result.transactions.map((row) => [row.date.toISOString(), row.description, row.transactionType, row.reference, row.direction, row.amount, row.balanceAfter])].map((row) => row.map(sanitizePayrollCsv).join(",")).join("\r\n")}`; };

const finalizedTaxSlips = (organizationId: string, year: number) => prisma.payslip.findMany({ where: { organizationId, payrollrun: { status: { in: [...payrollReportableStatuses] }, periodStart: { gte: new Date(Date.UTC(year, 0, 1)), lt: new Date(Date.UTC(year + 1, 0, 1)) } } }, include: { payrollrun: { select: { periodStart: true } } } });
const taxRows = async (organizationId: string, year: number, period?: string) => { const slips = await finalizedTaxSlips(organizationId, year); const currentPeriod = period ?? `${year}-${String(new Date().getUTCMonth() + 1).padStart(2, "0")}`; const rows = new Map<string, any>(); for (const slip of slips) { const row = rows.get(slip.employeeId) ?? { employee: { id: slip.employeeId, employeeId: slip.employeeNoSnapshot, fullName: slip.employeeNameSnapshot, role: slip.roleSnapshot }, department: { id: slip.departmentIdSnapshot, name: slip.departmentNameSnapshot }, tin: slip.tinSnapshot ? `***${slip.tinSnapshot.slice(-4)}` : null, state: slip.taxStateSnapshot ?? "UNCONFIGURED", authority: jsonRecord(slip.taxAuthoritySnapshot), currentGross: zeroDecimal(), currentPaye: zeroDecimal(), ytdGross: zeroDecimal(), ytdPaye: zeroDecimal() }; row.ytdGross = row.ytdGross.add(slip.grossPay); row.ytdPaye = row.ytdPaye.add(slip.payeTax); if (slip.payrollrun.periodStart.toISOString().slice(0, 7) === currentPeriod) { row.currentGross = row.currentGross.add(slip.grossPay); row.currentPaye = row.currentPaye.add(slip.payeTax); } rows.set(slip.employeeId, row); } return [...rows.values()].map((row) => ({ employee: row.employee, department: row.department, tin: row.tin, state: { code: row.state, name: row.state }, authority: { code: row.authority.code ?? null, name: row.authority.name ?? null, configured: Boolean(row.authority.configured) }, currentPeriod: { gross: Number(row.currentGross), paye: Number(row.currentPaye) }, ytd: { gross: Number(row.ytdGross), paye: Number(row.ytdPaye) }, effectiveRate: row.ytdGross.isZero() ? 0 : Number(row.ytdPaye.div(row.ytdGross).mul(100).toDecimalPlaces(2)) })); };
export const getPayrollTaxOverview = async (organizationId: string, query: any) => { await synchronizePayeRemittances(organizationId); const rows = await taxRows(organizationId, query.year, query.period); const remittances = await prisma.payrollTaxRemittance.findMany({ where: { organizationId, period: { startsWith: String(query.year) } } }); const authorities = new Set(rows.map((row) => row.authority.code ?? `STATE:${row.state.code}`)); const ytdPaye = rows.reduce((sum, row) => sum.add(row.ytd.paye), zeroDecimal()); const ytdRemitted = remittances.filter((row) => row.status === "REMITTED").reduce((sum, row) => sum.add(row.amount), zeroDecimal()); const nextDue = remittances.filter((row) => row.status !== "REMITTED" && row.dueDate && row.dueDate >= new Date()).sort((a, b) => a.dueDate!.getTime() - b.dueDate!.getTime())[0]?.dueDate ?? null; return { stateAuthorities: authorities.size, ytdPayeDeducted: Number(ytdPaye), ytdRemitted: Number(ytdRemitted), nextDueDate: nextDue, currency: "NGN" }; };
export const getPayrollTaxEmployeesByState = async (organizationId: string, query: any) => { let rows = await taxRows(organizationId, query.year, query.period); if (query.search) { const term = query.search.toLowerCase(); rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(term)); } if (query.state) rows = rows.filter((row) => row.state.code.toLowerCase() === query.state.toLowerCase()); if (query.authority) rows = rows.filter((row) => String(row.authority.code ?? "").toLowerCase() === query.authority.toLowerCase()); const total = rows.length; const items = rows.slice((query.page - 1) * query.limit, query.page * query.limit); const groups = new Map<string, any>(); for (const row of rows) { const key = row.authority.code ?? `STATE:${row.state.code}`; const group = groups.get(key) ?? { state: row.state, authority: row.authority, employeeCount: 0, currentPeriodPaye: 0 }; group.employeeCount += 1; group.currentPeriodPaye += row.currentPeriod.paye; groups.set(key, group); } return { groups: [...groups.values()], employees: items, pagination: payeePagination(query.page, query.limit, total) }; };
export const listPayrollTaxRemittances = async (organizationId: string, query: any) => { await synchronizePayeRemittances(organizationId); const now = new Date(); const where: Prisma.PayrollTaxRemittanceWhereInput = { organizationId, period: { startsWith: String(query.year) }, ...(query.period ? { period: query.period } : {}), ...(query.status === "REMITTED" ? { status: "REMITTED" } : query.status === "DUE" ? { status: { not: "REMITTED" }, OR: [{ dueDate: null }, { dueDate: { gte: now } }] } : query.status === "OVERDUE" ? { status: { not: "REMITTED" }, dueDate: { lt: now } } : {}) }; const [rows, total] = await Promise.all([prisma.payrollTaxRemittance.findMany({ where, orderBy: [{ period: "desc" }, { state: "asc" }], skip: (query.page - 1) * query.limit, take: query.limit }), prisma.payrollTaxRemittance.count({ where })]); return { remittances: rows.map((row) => ({ id: row.id, period: row.period, state: row.state, authority: { code: row.authorityCode, name: row.authorityName }, employees: row.employeeCount, payeAmount: Number(row.amount), dueDate: row.dueDate, status: row.status === "REMITTED" ? "REMITTED" : row.dueDate && row.dueDate < now ? "OVERDUE" : "DUE", remittedAt: row.remittedAt, paymentReference: row.paymentReference, receiptAvailable: Boolean(row.receiptReference) })), pagination: payeePagination(query.page, query.limit, total) }; };
export const getPayrollTaxAnnualReturns = async (organizationId: string, query: any) => { let rows = await taxRows(organizationId, query.year); if (query.search) rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(query.search.toLowerCase())); if (query.state) rows = rows.filter((row) => row.state.code.toLowerCase() === query.state.toLowerCase()); const total = rows.length; return { year: query.year, rows: rows.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, total) }; };
export const exportPayrollTaxAnnualReturns = async (organizationId: string, query: any) => { const result = await getPayrollTaxAnnualReturns(organizationId, { ...query, page: 1, limit: 100 }); return `\uFEFF${[["EmployeeID", "Employee", "Department", "State", "Authority", "TIN", "YTDGross", "YTDPAYE", "EffectiveRate"], ...result.rows.map((row) => [row.employee.employeeId, row.employee.fullName, row.department.name, row.state.name, row.authority.name, row.tin, row.ytd.gross, row.ytd.paye, row.effectiveRate])].map((row) => row.map(sanitizePayrollCsv).join(",")).join("\r\n")}`; };
export const getPayrollTaxConfig = async (organizationId: string, year: number) => { const resolved = await resolvePayrollStatutoryRule(organizationId, `${year}-12`); return { taxYear: year, bands: resolved.rule.paye.bands, annualDeductions: resolved.rule.paye.annualDeductions, pension: resolved.rule.pension, nhf: resolved.rule.nhf, source: resolved.source, version: resolved.rule.version, effectiveFrom: resolved.rule.effectiveFrom, versioned: true }; };
export const downloadPayrollTaxReceipt = async (organizationId: string, id: string) => { const row = await prisma.payrollTaxRemittance.findFirst({ where: { id, organizationId, status: "REMITTED" } }); if (!row?.receiptReference) throw notFound("Remittance receipt is not available"); const content = [`PAYE REMITTANCE RECEIPT`, `Period: ${row.period}`, `State: ${row.state}`, `Authority: ${row.authorityName ?? row.authorityCode}`, `Amount: ${row.amount.toFixed(2)}`, `Reference: ${row.paymentReference}`, `Remitted: ${row.remittedAt?.toISOString()}`].join("\n"); return { filename: `paye-remittance-${row.period}-${row.id}.txt`, buffer: Buffer.from(content, "utf8") }; };

const pensionConfig = async (organizationId: string) => { const row = await prisma.systemConfig.findUnique({ where: { organizationId_key: { organizationId, key: "payroll.pension.config" } }, select: { value: true } }); return jsonRecord(row?.value); };
const pensionDueDate = (period: string, dueDay: number | null) => { if (dueDay === null) return null; const [year, month] = period.split("-").map(Number); return new Date(Date.UTC(year, month, Math.min(Math.max(dueDay, 1), 28), 23, 59, 59, 999)); };
const synchronizePensionRemittances = async (organizationId: string) => { const config = await pensionConfig(organizationId); const dueDay = Number.isInteger(Number(config.remittanceDueDay)) ? Number(config.remittanceDueDay) : 7; const runs = await prisma.payrollRun.findMany({ where: { organizationId, status: { in: [...payrollReportableStatuses] } }, include: { payslip: { where: { pfaNameSnapshot: { not: null } }, select: { pfaNameSnapshot: true, pension: true, employerPension: true, avcContribution: true, employeeId: true } } } }); const writes: Prisma.PrismaPromise<unknown>[] = []; for (const run of runs) { const period = run.periodStart.toISOString().slice(0, 7); const groups = new Map<string, { members: Set<string>; employee: Prisma.Decimal; employer: Prisma.Decimal; avc: Prisma.Decimal }>(); for (const slip of run.payslip) { const pfa = slip.pfaNameSnapshot!.trim(); if (!pfa) continue; const group = groups.get(pfa) ?? { members: new Set(), employee: zeroDecimal(), employer: zeroDecimal(), avc: zeroDecimal() }; group.members.add(slip.employeeId); group.employee = group.employee.add(slip.pension); group.employer = group.employer.add(slip.employerPension); group.avc = group.avc.add(slip.avcContribution); groups.set(pfa, group); } for (const [pfaName, value] of groups) { const total = value.employee.add(value.employer).add(value.avc); writes.push(prisma.payrollPensionRemittance.upsert({ where: { organizationId_payrollRunId_pfaName: { organizationId, payrollRunId: run.id, pfaName } }, create: { organizationId, payrollRunId: run.id, period, pfaName, memberCount: value.members.size, employeeContribution: value.employee, employerContribution: value.employer, avcContribution: value.avc, totalAmount: total, dueDate: pensionDueDate(period, dueDay) }, update: {} })); } } if (writes.length) await prisma.$transaction(writes); };
const pensionContributionWhere = (organizationId: string, period?: string): Prisma.PayslipWhereInput => ({ organizationId, payrollrun: { status: { in: [...payrollReportableStatuses] }, ...(period ? { periodStart: { gte: new Date(`${period}-01T00:00:00.000Z`), lt: new Date(`${shiftPayrollMonth(period, 1)}-01T00:00:00.000Z`) } } : {}) } });
export const getPayrollPensionOverview = async (organizationId: string, query: any) => { const period = query.period ?? payrollPeriod(); await synchronizePensionRemittances(organizationId); const [slips, avcs, remittances, transfers] = await Promise.all([prisma.payslip.findMany({ where: pensionContributionWhere(organizationId, period), select: { employeeId: true, pfaNameSnapshot: true, pension: true, employerPension: true } }), prisma.payrollAvcContribution.findMany({ where: { organizationId, status: "ACTIVE", startDate: { lt: new Date(`${shiftPayrollMonth(period, 1)}-01T00:00:00.000Z`) }, OR: [{ endDate: null }, { endDate: { gte: new Date(`${period}-01T00:00:00.000Z`) } }] }, select: { monthlyAmount: true } }), prisma.payrollPensionRemittance.count({ where: { organizationId, period, status: { not: "REMITTED" } } }), prisma.payrollPfaTransfer.count({ where: { organizationId, status: { not: "COMPLETED" } } })]); const employee = slips.reduce((sum, row) => sum.add(row.pension), zeroDecimal()); const employer = slips.reduce((sum, row) => sum.add(row.employerPension), zeroDecimal()); const activeAvc = avcs.reduce((sum, row) => sum.add(row.monthlyAmount), zeroDecimal()); return { period, summary: { employeeContribution: Number(employee), employerContribution: Number(employer), totalMonthlyPension: Number(employee.add(employer)), activeAvcAmount: Number(activeAvc) }, counts: { employees: new Set(slips.map((row) => row.employeeId)).size, pfas: new Set(slips.map((row) => row.pfaNameSnapshot).filter(Boolean)).size, activeAvcs: avcs.length, pendingRemittances: remittances, activeTransfers: transfers } }; };
export const listPayrollPensionContributions = async (organizationId: string, query: any) => { const where = pensionContributionWhere(organizationId, query.period); const rows = await prisma.payslip.findMany({ where: { ...where, ...(query.pfa ? { pfaNameSnapshot: query.pfa } : {}), ...(query.search ? { OR: [{ employeeNameSnapshot: { contains: query.search } }, { employeeNoSnapshot: { contains: query.search } }, { pfaNameSnapshot: { contains: query.search } }] } : {}) }, include: { payrollrun: { select: { periodStart: true } } }, orderBy: [{ payrollrun: { periodStart: "desc" } }, { employeeNameSnapshot: "asc" }], skip: (query.page - 1) * query.limit, take: query.limit }); const total = await prisma.payslip.count({ where: { ...where, ...(query.pfa ? { pfaNameSnapshot: query.pfa } : {}), ...(query.search ? { OR: [{ employeeNameSnapshot: { contains: query.search } }, { employeeNoSnapshot: { contains: query.search } }, { pfaNameSnapshot: { contains: query.search } }] } : {}) } }); return { contributions: rows.map((row) => ({ id: row.id, employee: { id: row.employeeId, employeeId: row.employeeNoSnapshot, fullName: row.employeeNameSnapshot, department: row.departmentNameSnapshot, role: row.roleSnapshot }, pension: { pfaName: row.pfaNameSnapshot, pensionPin: maskIdentifier(row.pensionPinSnapshot) }, period: row.payrollrun.periodStart.toISOString().slice(0, 7), employeeContribution: Number(row.pension), employerContribution: Number(row.employerPension), avcContribution: Number(row.avcContribution), totalContribution: Number(row.pension.add(row.employerPension).add(row.avcContribution)) })), pagination: payeePagination(query.page, query.limit, total) }; };
export const listPayrollPfas = async (organizationId: string) => { const rows = await prisma.payrollStatutoryProfile.findMany({ where: { organizationId, pfaName: { not: null } }, select: { pfaName: true } }); return [...new Set(rows.map((row) => row.pfaName?.trim()).filter((value): value is string => Boolean(value)))].sort().map((name) => ({ id: name, name })); };
export const listPayrollPensionRemittances = async (organizationId: string, query: any) => { await synchronizePensionRemittances(organizationId); const where: Prisma.PayrollPensionRemittanceWhereInput = { organizationId, ...(query.period ? { period: query.period } : {}), ...(query.pfa ? { pfaName: query.pfa } : {}) }; const [rows, total] = await Promise.all([prisma.payrollPensionRemittance.findMany({ where, orderBy: [{ period: "desc" }, { pfaName: "asc" }], skip: (query.page - 1) * query.limit, take: query.limit }), prisma.payrollPensionRemittance.count({ where })]); return { remittances: rows.map((row) => ({ id: row.id, period: row.period, pfa: { id: row.pfaName, name: row.pfaName }, members: row.memberCount, employeeContribution: Number(row.employeeContribution), employerContribution: Number(row.employerContribution), avcContribution: Number(row.avcContribution), total: Number(row.totalAmount), dueDate: row.dueDate, status: row.status, remittedAt: row.remittedAt, reference: row.paymentReference })), pagination: payeePagination(query.page, query.limit, total) }; };
export const getPayrollPensionRemittance = async (organizationId: string, id: string) => { await synchronizePensionRemittances(organizationId); const row = await prisma.payrollPensionRemittance.findFirst({ where: { id, organizationId } }); if (!row) throw notFound("Pension remittance not found"); return row; };
export const markPayrollPensionRemitted = async (organizationId: string, id: string, input: any, user: AuthUser) => { const remittedAt = new Date(`${input.remittedAt}T12:00:00.000Z`); const row = await prisma.$transaction(async (tx) => { const changed = await tx.payrollPensionRemittance.updateMany({ where: { id, organizationId, status: { not: "REMITTED" } }, data: { status: "REMITTED", remittedAt, paymentReference: input.paymentReference, receiptReference: input.receiptReference ?? null, markedById: user.id } }); if (!changed.count) { const exists = await tx.payrollPensionRemittance.findFirst({ where: { id, organizationId } }); if (!exists) throw notFound("Pension remittance not found"); throw conflict("Pension remittance is already remitted"); } return tx.payrollPensionRemittance.findUniqueOrThrow({ where: { id } }); }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PENSION_REMITTANCE_MARKED", resource: "PAYROLL_PENSION_REMITTANCE", resourceId: id, summary: "Marked pension remittance as externally paid", metadata: { paymentReference: input.paymentReference } }); return row; };
export const listPayrollAvcs = async (organizationId: string, query: any) => { const where: Prisma.PayrollAvcContributionWhereInput = { organizationId, ...(query.search ? { employee: { OR: [{ firstName: { contains: query.search } }, { lastName: { contains: query.search } }, { employeeNo: { contains: query.search } }] } } : {}) }; const [rows, total] = await Promise.all([prisma.payrollAvcContribution.findMany({ where, include: { employee: { select: { id: true, employeeNo: true, firstName: true, lastName: true } } }, orderBy: { createdAt: "desc" }, skip: (query.page - 1) * query.limit, take: query.limit }), prisma.payrollAvcContribution.count({ where })]); return { avcs: rows.map((row) => ({ ...row, monthlyAmount: Number(row.monthlyAmount), employee: { id: row.employee.id, employeeId: row.employee.employeeNo, fullName: `${row.employee.firstName} ${row.employee.lastName}`.trim() } })), pagination: payeePagination(query.page, query.limit, total) }; };
export const createPayrollAvc = async (organizationId: string, input: any, user: AuthUser) => { const employee = await prisma.employee.findFirst({ where: { id: input.employeeId, organizationId, payrollEnrollment: { is: { isActive: true } }, payrollStatutoryProfile: { is: { pensionPin: { not: null }, pfaName: { not: null } } } }, select: { id: true } }); if (!employee) throw notFound("Eligible pension employee not found"); const existing = await prisma.payrollAvcContribution.findFirst({ where: { organizationId, employeeId: input.employeeId, status: "ACTIVE", OR: [{ endDate: null }, { endDate: { gte: new Date(`${input.startDate}T00:00:00.000Z`) } }] } }); if (existing) throw conflict("Employee already has an overlapping active AVC"); const row = await prisma.payrollAvcContribution.create({ data: { organizationId, employeeId: input.employeeId, monthlyAmount: input.monthlyAmount, startDate: new Date(`${input.startDate}T00:00:00.000Z`), createdById: user.id } }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PAYROLL_AVC_CREATED", resource: "PAYROLL_AVC", resourceId: row.id, summary: "Created voluntary pension contribution", metadata: { employeeId: input.employeeId } }); return { ...row, monthlyAmount: Number(row.monthlyAmount) }; };
export const setPayrollAvcPaused = async (organizationId: string, id: string, paused: boolean, user: AuthUser) => { const expected = paused ? "ACTIVE" : "PAUSED"; const next = paused ? "PAUSED" : "ACTIVE"; const now = new Date(); const changed = await prisma.payrollAvcContribution.updateMany({ where: { id, organizationId, status: expected }, data: { status: next, ...(paused ? { pausedAt: now } : { resumedAt: now }) } }); if (!changed.count) { const exists = await prisma.payrollAvcContribution.findFirst({ where: { id, organizationId } }); if (!exists) throw notFound("AVC not found"); throw conflict(`AVC cannot transition from ${exists.status} to ${next}`); } await createAuditLog({ organizationId, actorUserId: user.id, action: paused ? "PAYROLL_AVC_PAUSED" : "PAYROLL_AVC_RESUMED", resource: "PAYROLL_AVC", resourceId: id, summary: `${paused ? "Paused" : "Resumed"} voluntary pension contribution` }); return prisma.payrollAvcContribution.findUniqueOrThrow({ where: { id } }); };
const pfaTransferNext: Record<string, string> = { INITIATED: "PENCOM_REVIEW", PENCOM_REVIEW: "OLD_PFA_PROCESSING", OLD_PFA_PROCESSING: "NEW_PFA_CONFIRMATION", NEW_PFA_CONFIRMATION: "COMPLETED" };
export const listPayrollPfaTransfers = async (organizationId: string, query: any) => { const where: Prisma.PayrollPfaTransferWhereInput = { organizationId, ...(query.search ? { employee: { OR: [{ firstName: { contains: query.search } }, { lastName: { contains: query.search } }, { employeeNo: { contains: query.search } }] } } : {}) }; const [rows, total] = await Promise.all([prisma.payrollPfaTransfer.findMany({ where, include: { employee: { select: { id: true, employeeNo: true, firstName: true, lastName: true } } }, orderBy: { initiatedAt: "desc" }, skip: (query.page - 1) * query.limit, take: query.limit }), prisma.payrollPfaTransfer.count({ where })]); return { transfers: rows.map((row) => ({ ...row, employee: { id: row.employee.id, employeeId: row.employee.employeeNo, fullName: `${row.employee.firstName} ${row.employee.lastName}`.trim() } })), pagination: payeePagination(query.page, query.limit, total) }; };
export const getPayrollPfaTransfer = async (organizationId: string, id: string) => { const row = await prisma.payrollPfaTransfer.findFirst({ where: { id, organizationId }, include: { employee: { select: { id: true, employeeNo: true, firstName: true, lastName: true } } } }); if (!row) throw notFound("PFA transfer not found"); return row; };
export const createPayrollPfaTransfer = async (organizationId: string, input: any, user: AuthUser) => { const profile = await prisma.payrollStatutoryProfile.findFirst({ where: { organizationId, employeeId: input.employeeId }, select: { pfaName: true } }); if (!profile?.pfaName) throw notFound("Employee pension profile not found"); if (profile.pfaName.trim().toLowerCase() !== input.currentPfa.trim().toLowerCase()) throw conflict("Current PFA does not match the employee pension profile"); const active = await prisma.payrollPfaTransfer.findFirst({ where: { organizationId, employeeId: input.employeeId, status: { not: "COMPLETED" } } }); if (active) throw conflict("Employee already has an unresolved PFA transfer"); const row = await prisma.payrollPfaTransfer.create({ data: { organizationId, employeeId: input.employeeId, fromPfaName: profile.pfaName, toPfaName: input.newPfa, externalReference: input.externalReference, createdById: user.id } }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PFA_TRANSFER_INITIATED", resource: "PAYROLL_PFA_TRANSFER", resourceId: row.id, summary: "Initiated employee PFA transfer", metadata: { employeeId: input.employeeId, fromPfa: profile.pfaName, toPfa: input.newPfa } }); return row; };
export const advancePayrollPfaTransfer = async (organizationId: string, id: string, input: any, user: AuthUser) => { const result = await prisma.$transaction(async (tx) => { const transfer = await tx.payrollPfaTransfer.findFirst({ where: { id, organizationId } }); if (!transfer) throw notFound("PFA transfer not found"); if (pfaTransferNext[transfer.status] !== input.nextStatus) throw conflict(`PFA transfer cannot transition from ${transfer.status} to ${input.nextStatus}`); const now = new Date(); const updated = await tx.payrollPfaTransfer.update({ where: { id }, data: { status: input.nextStatus, updatedById: user.id, externalReference: input.externalReference ?? transfer.externalReference, ...(input.nextStatus === "COMPLETED" ? { completedAt: now } : {}) } }); if (input.nextStatus === "COMPLETED") await tx.payrollStatutoryProfile.update({ where: { employeeId: transfer.employeeId }, data: { pfaName: transfer.toPfaName } }); return { previousStatus: transfer.status, transfer: updated }; }); await createAuditLog({ organizationId, actorUserId: user.id, action: result.transfer.status === "COMPLETED" ? "PFA_TRANSFER_COMPLETED" : "PFA_TRANSFER_ADVANCED", resource: "PAYROLL_PFA_TRANSFER", resourceId: id, summary: "Advanced PFA transfer workflow", metadata: { previousStatus: result.previousStatus, newStatus: result.transfer.status } }); return result.transfer; };
export const exportPayrollPension = async (organizationId: string, query: any) => { const result = await listPayrollPensionContributions(organizationId, { ...query, page: 1, limit: 100 }); const rows = result.contributions.map((row) => [row.period, row.employee.employeeId, row.employee.fullName, row.pension.pfaName, row.pension.pensionPin, row.employeeContribution, row.employerContribution, row.avcContribution, row.totalContribution]); return `\uFEFF${[["Period", "EmployeeID", "Employee", "PFA", "PensionPIN", "EmployeeContribution", "EmployerContribution", "AVC", "Total"], ...rows].map((row) => row.map(sanitizePayrollCsv).join(",")).join("\r\n")}`; };

const reportSlips = (organizationId: string, from: Date, to: Date) => prisma.payslip.findMany({ where: { organizationId, payrollrun: { status: { in: [...payrollReportableStatuses] }, periodStart: { gte: from, lt: to } } }, include: { payrollrun: { select: { id: true, name: true, periodStart: true } } } });
const reportPeriodRange = (period: string) => ({ from: new Date(`${period}-01T00:00:00.000Z`), to: new Date(`${shiftPayrollMonth(period, 1)}-01T00:00:00.000Z`) });
export const getPayrollReportSummary = async (organizationId: string, query: any) => { const from = new Date(Date.UTC(query.year, 0, 1)); const to = new Date(Date.UTC(query.year + 1, 0, 1)); const slips = await reportSlips(organizationId, from, to); const months = new Map<string, any>(); for (const row of slips) { const period = row.payrollrun.periodStart.toISOString().slice(0, 7); const bucket = months.get(period) ?? { period, employees: new Set<string>(), gross: zeroDecimal(), netPay: zeroDecimal(), paye: zeroDecimal(), employeePension: zeroDecimal(), employerPension: zeroDecimal(), nhf: zeroDecimal(), employerCost: zeroDecimal() }; bucket.employees.add(row.employeeId); bucket.gross = bucket.gross.add(row.grossPay); bucket.netPay = bucket.netPay.add(row.netPay); bucket.paye = bucket.paye.add(row.payeTax); bucket.employeePension = bucket.employeePension.add(row.pension); bucket.employerPension = bucket.employerPension.add(row.employerPension); bucket.nhf = bucket.nhf.add(row.nhf); bucket.employerCost = bucket.employerCost.add(row.grossPay).add(row.employerPension).add(row.nsitf); months.set(period, bucket); } const breakdown = [...months.values()].sort((a, b) => a.period.localeCompare(b.period)).map((row) => ({ period: row.period, employeeCount: row.employees.size, gross: Number(row.gross), netPay: Number(row.netPay), paye: Number(row.paye), employeePension: Number(row.employeePension), employerPension: Number(row.employerPension), nhf: Number(row.nhf), employerCost: Number(row.employerCost) })); const selected = query.period ? breakdown.find((row) => row.period === query.period) ?? null : breakdown.at(-1) ?? null; return { period: selected?.period ?? query.period ?? null, year: query.year, summary: { gross: selected?.gross ?? 0, netPay: selected?.netPay ?? 0, employerCost: selected?.employerCost ?? 0, employeeCount: selected?.employeeCount ?? 0, ytdCost: Number(breakdown.reduce((sum, row) => sum.add(row.employerCost), zeroDecimal())) }, monthlyTrend: breakdown.map(({ period, gross, netPay }) => ({ period, gross, netPay })), monthlyBreakdown: breakdown }; };
export const getPayrollDepartmentCostReport = async (organizationId: string, query: any) => { const range = reportPeriodRange(query.period); const slips = await reportSlips(organizationId, range.from, range.to); const totalGross = slips.reduce((sum, row) => sum.add(row.grossPay), zeroDecimal()); const groups = new Map<string, any>(); for (const row of slips) { const key = row.departmentIdSnapshot ?? `name:${row.departmentNameSnapshot ?? "Unassigned"}`; const group = groups.get(key) ?? { departmentId: row.departmentIdSnapshot, departmentName: row.departmentNameSnapshot ?? "Unassigned", employees: new Set<string>(), gross: zeroDecimal(), netPay: zeroDecimal() }; group.employees.add(row.employeeId); group.gross = group.gross.add(row.grossPay); group.netPay = group.netPay.add(row.netPay); groups.set(key, group); } const all = [...groups.values()].map((row) => ({ departmentId: row.departmentId, departmentName: row.departmentName, employeeCount: row.employees.size, gross: Number(row.gross), netPay: Number(row.netPay), percentageOfTotal: totalGross.isZero() ? 0 : Number(row.gross.div(totalGross).mul(100).toDecimalPlaces(2)) })).sort((a, b) => b.gross - a.gross); return { period: query.period, totalGross: Number(totalGross), departments: all.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, all.length) }; };
export const getPayrollVarianceReport = async (organizationId: string, query: any) => { const previousRange = reportPeriodRange(query.previousPeriod); const currentRange = reportPeriodRange(query.currentPeriod); const [previous, current] = await Promise.all([reportSlips(organizationId, previousRange.from, previousRange.to), reportSlips(organizationId, currentRange.from, currentRange.to)]); const prior = new Map(previous.map((row) => [row.employeeId, row])); const present = new Map(current.map((row) => [row.employeeId, row])); const ids = new Set([...prior.keys(), ...present.keys()]); let rows = [...ids].map((id) => { const before = prior.get(id); const after = present.get(id); const previousNet = before?.netPay ?? zeroDecimal(); const currentNet = after?.netPay ?? zeroDecimal(); const variance = currentNet.sub(previousNet); const changeType = !before ? "NEW_EMPLOYEE" : !after ? "REMOVED_EMPLOYEE" : variance.gt(0) ? "INCREASE" : variance.lt(0) ? "DECREASE" : "NO_CHANGE"; return { employee: { id, employeeId: after?.employeeNoSnapshot ?? before?.employeeNoSnapshot, fullName: after?.employeeNameSnapshot ?? before?.employeeNameSnapshot }, previousNet: Number(previousNet), currentNet: Number(currentNet), variance: Number(variance), percentageChange: previousNet.isZero() ? null : Number(variance.div(previousNet).mul(100).toDecimalPlaces(2)), changeType }; }); if (query.search) rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(query.search.toLowerCase())); return { previousPeriod: query.previousPeriod, currentPeriod: query.currentPeriod, rows: rows.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, rows.length) }; };
export const getPayrollBankScheduleReport = async (organizationId: string, query: any) => { const range = reportPeriodRange(query.period); let rows = await reportSlips(organizationId, range.from, range.to); if (query.status) rows = rows.filter((row) => row.paymentStatus === query.status); if (query.search) rows = rows.filter((row) => `${row.employeeNameSnapshot} ${row.employeeNoSnapshot}`.toLowerCase().includes(query.search.toLowerCase())); const mapped = rows.map((row, index) => ({ number: index + 1, payslipId: row.id, employee: { id: row.employeeId, employeeId: row.employeeNoSnapshot, fullName: row.employeeNameSnapshot }, bank: jsonRecord(row.bankSnapshot), amount: Number(row.netPay), status: row.paymentStatus })); return { period: query.period, rows: mapped.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, mapped.length) }; };
export const getPayrollYtdReport = async (organizationId: string, query: any) => { const slips = await reportSlips(organizationId, new Date(Date.UTC(query.year, 0, 1)), new Date(Date.UTC(query.year + 1, 0, 1))); const groups = new Map<string, any>(); for (const row of slips) { if (query.departmentId && row.departmentIdSnapshot !== query.departmentId) continue; const group = groups.get(row.employeeId) ?? { employee: { id: row.employeeId, employeeId: row.employeeNoSnapshot, fullName: row.employeeNameSnapshot }, department: { id: row.departmentIdSnapshot, name: row.departmentNameSnapshot }, gross: zeroDecimal(), paye: zeroDecimal(), pension: zeroDecimal(), net: zeroDecimal() }; group.gross = group.gross.add(row.grossPay); group.paye = group.paye.add(row.payeTax); group.pension = group.pension.add(row.pension).add(row.avcContribution); group.net = group.net.add(row.netPay); groups.set(row.employeeId, group); } let rows = [...groups.values()].map((row) => ({ employee: row.employee, department: row.department, ytdGross: Number(row.gross), ytdPaye: Number(row.paye), ytdPension: Number(row.pension), ytdNet: Number(row.net) })); if (query.search) rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(query.search.toLowerCase())); return { year: query.year, pensionMeaning: "EMPLOYEE_STATUTORY_PLUS_AVC", rows: rows.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, rows.length) }; };
const reportCsv = (headers: string[], rows: unknown[][]) => `\uFEFF${[headers, ...rows].map((row) => row.map(sanitizePayrollCsv).join(",")).join("\r\n")}`;
export const exportPayrollReport = async (organizationId: string, kind: string, query: any, user: AuthUser) => { let csv = ""; if (kind === "summary") { const data = await getPayrollReportSummary(organizationId, query); csv = reportCsv(["Period", "Gross", "NetPay", "PAYE", "EmployeePension", "EmployerPension", "NHF", "EmployerCost"], data.monthlyBreakdown.map((row) => [row.period, row.gross, row.netPay, row.paye, row.employeePension, row.employerPension, row.nhf, row.employerCost])); } else if (kind === "department") { const data = await getPayrollDepartmentCostReport(organizationId, { ...query, page: 1, limit: 100 }); csv = reportCsv(["Department", "Employees", "Gross", "NetPay", "PercentageOfTotal"], data.departments.map((row) => [row.departmentName, row.employeeCount, row.gross, row.netPay, row.percentageOfTotal])); } else if (kind === "variance") { const data = await getPayrollVarianceReport(organizationId, { ...query, page: 1, limit: 100 }); csv = reportCsv(["EmployeeID", "Employee", "PreviousNet", "CurrentNet", "Variance", "PercentageChange", "Change"], data.rows.map((row) => [row.employee.employeeId, row.employee.fullName, row.previousNet, row.currentNet, row.variance, row.percentageChange, row.changeType])); } else if (kind === "bank") { const data = await getPayrollBankScheduleReport(organizationId, { ...query, page: 1, limit: 100 }); csv = reportCsv(["EmployeeID", "Employee", "Bank", "AccountNumber", "AccountName", "Amount", "Status"], data.rows.map((row) => [row.employee.employeeId, row.employee.fullName, row.bank.bankName, row.bank.accountNumber, row.bank.accountName, row.amount, row.status])); } else { const data = await getPayrollYtdReport(organizationId, { ...query, page: 1, limit: 100 }); csv = reportCsv(["EmployeeID", "Employee", "Department", "YTDGross", "YTDPAYE", "YTDPension", "YTDNet"], data.rows.map((row) => [row.employee.employeeId, row.employee.fullName, row.department.name, row.ytdGross, row.ytdPaye, row.ytdPension, row.ytdNet])); } await createAuditLog({ organizationId, actorUserId: user.id, action: "PAYROLL_REPORT_EXPORTED", resource: "PAYROLL_REPORT", resourceId: kind, summary: `Exported ${kind} payroll report` }); return csv; };

const PAYROLL_SETTING_KEYS = { payPeriod: "payroll.settings.pay-period", allowances: "payroll.settings.allowance-types", deductions: "payroll.settings.deduction-types" } as const;
const payrollSettingRecord = (value: Prisma.JsonValue | null | undefined): Record<string, any> => value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : {};
const payrollSettingList = (value: Prisma.JsonValue | null | undefined): any[] => Array.isArray(value) ? value : [];
const normalizePayrollTypeName = (name: string) => name.trim().replace(/\s+/g, " ");
const systemAllowanceTypes = [
  { id: "BASIC", code: "BASIC", name: "Basic Salary", taxTreatment: "TAXABLE", systemDefined: true, active: true },
  { id: "HOUSING", code: "HOUSING", name: "Housing Allowance", taxTreatment: "TAXABLE", systemDefined: true, active: true },
  { id: "TRANSPORT", code: "TRANSPORT", name: "Transport Allowance", taxTreatment: "TAXABLE", systemDefined: true, active: true },
  { id: "OTHER_ALLOWANCE", code: "OTHER_ALLOWANCE", name: "Other Allowance", taxTreatment: "TAXABLE", systemDefined: true, active: true }
] as const;
const systemDeductionTypes = [
  { id: "PAYE", code: "PAYE", name: "PAYE", category: "STATUTORY", systemDefined: true, active: true },
  { id: "EMPLOYEE_PENSION", code: "EMPLOYEE_PENSION", name: "Employee Pension", category: "STATUTORY", systemDefined: true, active: true },
  { id: "NHF", code: "NHF", name: "NHF", category: "STATUTORY", systemDefined: true, active: true },
  { id: "LOAN_REPAYMENT", code: "LOAN_REPAYMENT", name: "Loan Repayment", category: "VOLUNTARY", systemDefined: true, active: true }
] as const;
const payrollTypeDto = (item: any) => ({ ...item, removable: !item.systemDefined, editable: !item.systemDefined });
const payrollSetting = (organizationId: string, key: string) => prisma.systemConfig.findUnique({ where: { organizationId_key: { organizationId, key } } });
const savePayrollSettingList = async (organizationId: string, key: string, value: any[], user: AuthUser, expectedVersion: number | null) => {
  if (expectedVersion === null) {
    try { return await prisma.systemConfig.create({ data: { organizationId, key, value, updatedByUserId: user.id, updateSource: "PAYROLL_SETTINGS" } }); }
    catch (error) { if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2002") throw conflict("Payroll settings changed concurrently; reload and retry"); throw error; }
  }
  const updated = await prisma.systemConfig.updateMany({ where: { organizationId, key, rowVersion: expectedVersion }, data: { value, updatedByUserId: user.id, updateSource: "PAYROLL_SETTINGS", rowVersion: { increment: 1 } } });
  if (!updated.count) throw conflict("Payroll settings changed concurrently; reload and retry");
  return prisma.systemConfig.findUniqueOrThrow({ where: { organizationId_key: { organizationId, key } } });
};

export const effectiveMonthlyPayDate = (period: string, day: number) => { const [year, month] = period.split("-").map(Number); const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate(); return new Date(Date.UTC(year, month - 1, Math.min(day, lastDay))); };
export const getPayrollPayPeriodSettings = async (organizationId: string) => { const row = await payrollSetting(organizationId, PAYROLL_SETTING_KEYS.payPeriod); const value = payrollSettingRecord(row?.value); return { payFrequency: "MONTHLY" as const, defaultPayDay: Number.isInteger(value.defaultPayDay) ? value.defaultPayDay : 25, version: row?.rowVersion ?? 0, updatedAt: row?.updatedAt ?? null }; };
export const updatePayrollPayPeriodSettings = async (organizationId: string, input: any, user: AuthUser) => { const before = await getPayrollPayPeriodSettings(organizationId); const row = await prisma.systemConfig.upsert({ where: { organizationId_key: { organizationId, key: PAYROLL_SETTING_KEYS.payPeriod } }, create: { organizationId, key: PAYROLL_SETTING_KEYS.payPeriod, value: input, updatedByUserId: user.id, updateSource: "PAYROLL_SETTINGS" }, update: { value: input, updatedByUserId: user.id, updateSource: "PAYROLL_SETTINGS", rowVersion: { increment: 1 } } }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PAYROLL_PAY_PERIOD_SETTINGS_UPDATED", resource: "SYSTEM_CONFIG", resourceId: row.id, summary: "Updated Payroll pay-period settings", metadata: { before: { payFrequency: before.payFrequency, defaultPayDay: before.defaultPayDay }, after: input } }); return getPayrollPayPeriodSettings(organizationId); };
export const listPayrollAllowanceTypes = async (organizationId: string) => [...systemAllowanceTypes, ...payrollSettingList((await payrollSetting(organizationId, PAYROLL_SETTING_KEYS.allowances))?.value)].map(payrollTypeDto);
export const listPayrollDeductionTypes = async (organizationId: string) => [...systemDeductionTypes, ...payrollSettingList((await payrollSetting(organizationId, PAYROLL_SETTING_KEYS.deductions))?.value)].map(payrollTypeDto);
const createPayrollType = async (organizationId: string, key: string, input: any, user: AuthUser, kind: "ALLOWANCE" | "DEDUCTION") => { const settingsRow = await payrollSetting(organizationId, key); const custom = payrollSettingList(settingsRow?.value); const name = normalizePayrollTypeName(input.name); const system = kind === "ALLOWANCE" ? systemAllowanceTypes : systemDeductionTypes; if ([...system, ...custom].some((item) => item.active && item.name.toLowerCase() === name.toLowerCase())) throw conflict(`An active ${kind.toLowerCase()} type with this name already exists`); const item = { id: crypto.randomUUID(), name, ...(kind === "ALLOWANCE" ? { taxTreatment: input.taxTreatment } : { category: "VOLUNTARY" }), systemDefined: false, active: true, createdBy: user.id, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; await savePayrollSettingList(organizationId, key, [...custom, item], user, settingsRow?.rowVersion ?? null); await createAuditLog({ organizationId, actorUserId: user.id, action: `PAYROLL_${kind}_TYPE_CREATED`, resource: `PAYROLL_${kind}_TYPE`, resourceId: item.id, summary: `Created ${kind.toLowerCase()} type ${name}`, metadata: kind === "ALLOWANCE" ? { taxTreatment: input.taxTreatment } : undefined }); return payrollTypeDto(item); };
const updatePayrollType = async (organizationId: string, key: string, id: string, input: any, user: AuthUser, kind: "ALLOWANCE" | "DEDUCTION") => { const settingsRow = await payrollSetting(organizationId, key); const custom = payrollSettingList(settingsRow?.value); const index = custom.findIndex((item) => item.id === id); if (index < 0) { if ([...systemAllowanceTypes, ...systemDeductionTypes].some((item) => item.id === id)) throw conflict("System-defined payroll types cannot be changed or removed"); throw notFound(`${kind === "ALLOWANCE" ? "Allowance" : "Deduction"} type not found`); } const name = input.name ? normalizePayrollTypeName(input.name) : custom[index].name; if (custom.some((item, position) => position !== index && item.active && item.name.toLowerCase() === name.toLowerCase())) throw conflict(`An active ${kind.toLowerCase()} type with this name already exists`); const before = custom[index]; custom[index] = { ...before, ...input, name, updatedAt: new Date().toISOString() }; await savePayrollSettingList(organizationId, key, custom, user, settingsRow?.rowVersion ?? null); await createAuditLog({ organizationId, actorUserId: user.id, action: `PAYROLL_${kind}_TYPE_UPDATED`, resource: `PAYROLL_${kind}_TYPE`, resourceId: id, summary: `Updated ${kind.toLowerCase()} type ${name}`, metadata: { before, after: custom[index] } }); return payrollTypeDto(custom[index]); };
export const createPayrollAllowanceType = (organizationId: string, input: any, user: AuthUser) => createPayrollType(organizationId, PAYROLL_SETTING_KEYS.allowances, input, user, "ALLOWANCE");
export const updatePayrollAllowanceType = (organizationId: string, id: string, input: any, user: AuthUser) => updatePayrollType(organizationId, PAYROLL_SETTING_KEYS.allowances, id, input, user, "ALLOWANCE");
export const removePayrollAllowanceType = (organizationId: string, id: string, user: AuthUser) => updatePayrollType(organizationId, PAYROLL_SETTING_KEYS.allowances, id, { active: false }, user, "ALLOWANCE");
export const createPayrollDeductionType = (organizationId: string, input: any, user: AuthUser) => createPayrollType(organizationId, PAYROLL_SETTING_KEYS.deductions, input, user, "DEDUCTION");
export const updatePayrollDeductionType = (organizationId: string, id: string, input: any, user: AuthUser) => updatePayrollType(organizationId, PAYROLL_SETTING_KEYS.deductions, id, input, user, "DEDUCTION");
export const removePayrollDeductionType = (organizationId: string, id: string, user: AuthUser) => updatePayrollType(organizationId, PAYROLL_SETTING_KEYS.deductions, id, { active: false }, user, "DEDUCTION");
export const getPayrollStatutoryRates = async (organizationId: string, period = payrollPeriod()) => { const resolved = await resolvePayrollStatutoryRule(organizationId, period); return { ...resolved.rule, source: resolved.source, readOnly: true, rowVersion: resolved.rowVersion }; };
export const getPayrollSettingsOverview = async (organizationId: string) => { const [payPeriod, allowanceTypes, deductionTypes, statutoryRates] = await Promise.all([getPayrollPayPeriodSettings(organizationId), listPayrollAllowanceTypes(organizationId), listPayrollDeductionTypes(organizationId), getPayrollStatutoryRates(organizationId)]); return { payPeriod, allowanceTypes, deductionTypes, statutoryRates }; };

export const isMutablePayrollRunStatus = (status: string) => status === "DRAFT" || status === "PROCESSING";
